"""New fact-hunt questions for Skim & scan, written for the findable detail rather than the gist.

SCAN_NEW[id] = [(question, correct answer, [3 wrong answers], evidence fragment), ...]
The evidence fragment must occur exactly in the excerpt; the build expands it to its full sentence so the
app can highlight it. Wrong answers must NOT appear in the excerpt (checked by the build).
"""
SCAN_NEW = {}
def add(sid, q, correct, w1, w2, w3, evidence):
    SCAN_NEW.setdefault(sid, []).append((q, correct, [w1, w2, w3], evidence))

